<template><div class="login-wrap"><div class="login-card"><h2>企业经营风险智能分析平台</h2><p class="muted">Java + 风险规则 + RAG + Agent</p><el-form @keyup.enter="submit"><el-form-item><el-input v-model="form.username" size="large" placeholder="用户名"/></el-form-item><el-form-item><el-input v-model="form.password" size="large" type="password" show-password placeholder="密码"/></el-form-item><el-button type="primary" size="large" style="width:100%" :loading="loading" @click="submit">登录</el-button></el-form><p class="muted">admin / Admin@123</p></div></div></template><script setup>import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';const form=reactive({username:'admin',password:'Admin@123'}),loading=ref(false),router=useRouter(),auth=useAuthStore();async function submit(){loading.value=true;try{await auth.login(form);router.push('/dashboard')}finally{loading.value=false}}</script>
